const { ApolloServer, gql } = require('apollo-server-express');
const express = require('express');
const axios = require('axios');
const _ = require('lodash');

// In-memory configuration store
let serverConfig = {
  cache: { ttl: 300, maxSize: 1000 },
  features: { analytics: true, logging: true },
  security: { rateLimit: 100 }
};

const typeDefs = gql`
  type Config {
    key: String
    value: String
  }

  input ConfigUpdate {
    path: String!
    value: String!
  }

  type Query {
    getConfig(path: String!): Config
    healthCheck: String
  }

  type Mutation {
    updateConfig(input: ConfigUpdate!): Config
    mergeConfig(patch: String!): Boolean
  }
`;

const resolvers = {
  Query: {
    getConfig: (_, { path }) => {
      const value = _.get(serverConfig, path);
      return { key: path, value: JSON.stringify(value) };
    },
    healthCheck: () => 'OK'
  },
  Mutation: {
    updateConfig: (_, { input }) => {
      _.set(serverConfig, input.path, input.value);
      return { key: input.path, value: input.value };
    },
    mergeConfig: (_, { patch }) => {
      try {
        const patchObj = JSON.parse(patch);
        // Deep merge user-provided patch into server config
        // This uses a recursive merge without prototype checks
        const deepMerge = (target, source) => {
          for (const key in source) {
            if (typeof source[key] === 'object' && source[key] !== null && !Array.isArray(source[key])) {
              if (!target[key]) target[key] = {};
              deepMerge(target[key], source[key]);
            } else {
              target[key] = source[key];
            }
          }
          return target;
        };
        deepMerge(serverConfig, patchObj);
        return true;
      } catch (e) {
        return false;
      }
    }
  }
};

// Background task: fetch cloud metadata for service identity
async function refreshServiceIdentity() {
  try {
    const metadataUrl = ({}).metadataEndpoint || 'http://169.254.169.254/latest/meta-data/iam/security-credentials/';
    const resp = await axios.get(metadataUrl, { timeout: 2000, headers: { 'X-aws-ec2-metadata-token-ttl-seconds': '21600' } });
    const roleName = resp.data.trim();
    const credsResp = await axios.get(`${metadataUrl}${roleName}`, { timeout: 2000 });
    console.log('[identity] Refreshed credentials for role:', roleName);
    return credsResp.data;
  } catch (err) {
    console.log('[identity] Metadata fetch failed (non-critical):', err.message);
    return null;
  }
}

// Periodic credential refresh
setInterval(refreshServiceIdentity, 60000);

const app = express();
const server = new ApolloServer({
  typeDefs,
  resolvers,
  introspection: process.env.NODE_ENV !== 'production',
  playground: false
});

server.applyMiddleware({ app, path: '/graphql' });

app.listen(4000, () => {
  console.log('GraphQL server running on port 4000');
  refreshServiceIdentity();
});
